// Map the containers list from parsed SSH JSON to Supabase schema format
const containers = $json.containers || [];
const mapped = containers.map(c => {
  // Normalize Docker "Up X hours" to standard "running"
  let status = c.status || '';
  if (status.toLowerCase().startsWith('up')) {
    status = 'running';
  }
  return {
    id: c.name,
    name: c.name,
    status: status,
    cpu_percent: c.cpu_percent,
    ram_bytes: c.ram_bytes,
    updated_at: new Date().toISOString()
  };
});
return [ { json: { containers: mapped } } ];

