import json
import os
import shutil
import time
import subprocess
import re

def get_cpu_model():
    try:
        with open("/proc/cpuinfo", "r") as f:
            for line in f:
                if "model name" in line:
                    return re.sub(r"model name\s*:\s*", "", line).strip()
    except:
        pass
    return "AMD EPYC"

def get_cpu_usage():
    try:
        with open("/proc/loadavg", "r") as f:
            loadavg = f.read().strip().split()
        load_5 = float(loadavg[1])
        cpu_cores = os.cpu_count() or 1
        return min(round((load_5 / cpu_cores) * 100, 1), 100.0)
    except:
        pass
    return 10.0

def get_ram_info():
    try:
        # Read /proc/meminfo
        mem_info = {}
        with open("/proc/meminfo", "r") as f:
            for line in f:
                parts = line.split(":")
                if len(parts) == 2:
                    key = parts[0].strip()
                    val = parts[1].replace("kB", "").strip()
                    mem_info[key] = int(val) * 1024

        total = mem_info.get("MemTotal", 4 * 1024 * 1024 * 1024)
        free = mem_info.get("MemFree", 0)
        buffers = mem_info.get("Buffers", 0)
        cached = mem_info.get("Cached", 0)
        reclaimable = mem_info.get("SReclaimable", 0)

        # Available memory (more accurate than Free)
        available = mem_info.get("MemAvailable", free + buffers + cached + reclaimable)
        used = total - available
        usage_pct = round((used / total) * 100, 1)

        return total, used, usage_pct
    except:
        pass
    return 4 * 1024 * 1024 * 1024, 2 * 1024 * 1024 * 1024, 50.0

def parse_bytes(val_str):
    try:
        val_str = val_str.strip()
        val = float(re.search(r"[0-9.]+", val_str).group())
        unit = re.search(r"[A-Za-z]+", val_str).group().upper()
        if "G" in unit:
            return int(val * 1024 * 1024 * 1024)
        elif "M" in unit:
            return int(val * 1024 * 1024)
        elif "K" in unit:
            return int(val * 1024)
    except:
        pass
    return 0

def get_containers_info():
    containers = []
    try:
        # Get docker ps
        ps_out = subprocess.check_output(["docker", "ps", "--format", "{{json .}}"]).decode("utf-8")
        running_names = {}
        for line in ps_out.strip().split("\n"):
            if not line: continue
            data = json.loads(line)
            running_names[data["Names"]] = data["Status"]

        # Get docker stats
        stats_out = subprocess.check_output(["docker", "stats", "--no-stream", "--format", "{{json .}}"]).decode("utf-8")
        for line in stats_out.strip().split("\n"):
            if not line: continue
            data = json.loads(line)
            name = data["Name"]
            if name in running_names:
                # Parse CPU percent
                cpu = float(data["CPUPerc"].replace("%", "").strip())
                # Parse memory usage (e.g. "234.5MiB / 3.858GiB")
                mem_usage = data["MemUsage"].split("/")[0].strip()
                ram_bytes = parse_bytes(mem_usage)

                containers.append({
                    "name": name,
                    "status": running_names[name],
                    "cpu_percent": cpu,
                    "ram_bytes": ram_bytes
                })
    except Exception as e:
        pass
    return containers

def main():
    ram_total, ram_used, ram_usage = get_ram_info()

    # Disk info
    total_disk, used_disk, free_disk = shutil.disk_usage("/")
    disk_usage = round((used_disk / total_disk) * 100, 1)

    # CPU
    cpu_cores = os.cpu_count()
    cpu_model = get_cpu_model()
    cpu_usage = get_cpu_usage()

    # Containers
    containers = get_containers_info()

    result = {
        "cpu_usage": cpu_usage,
        "ram_usage": ram_usage,
        "ram_used": ram_used,
        "ram_total": ram_total,
        "disk_usage": disk_usage,
        "disk_used": used_disk,
        "disk_total": total_disk,
        "cpu_cores": cpu_cores,
        "cpu_model": cpu_model,
        "containers": containers
    }

    print(json.dumps(result))

if __name__ == '__main__':
    main()

